import {breeds,defaults,normalizeProfile,rankBreeds,restoreState,discoveryRound,matchesCoat,needsCarePlan,fluffLevels} from '../engine.mjs?v=22';
import {dogProfiles} from '../profiles.mjs?v=22';
import {reorderCompared} from '../comparison-tools.mjs';
import {chapters,questions,activeQuestions,duration,answerText} from './questions.mjs';
const $=id=>document.getElementById(id),screen=$('screen'),storageKey='pawfect-prototype-v2',preferenceKey='pawfect-prototype-v2-preferences';
const ids=new Set(breeds.map(b=>b.id));
const paw='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><ellipse cx="6" cy="8" rx="2.2" ry="3" fill="currentColor"/><ellipse cx="11" cy="5" rx="2" ry="2.7" fill="currentColor"/><ellipse cx="17" cy="6" rx="2" ry="2.8" fill="currentColor"/><ellipse cx="21" cy="11" rx="1.8" ry="2.5" fill="currentColor"/><path d="M6 17c0-3 3-7 6-7s7 4 7 7c0 4-4 2-6 2s-7 2-7-2" fill="currentColor"/></svg>';
function heart(saved){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z" fill="${saved?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7"/></svg>`;}
const fresh=()=>({version:1,profile:{...defaults},step:0,completed:false,favorites:[],compare:[],history:[],answered:[],question:'home',topPick:null});
let state=fresh(),prefs={size:100,motion:false,theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'},storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(storageKey));if(raw){state={...restoreState(raw),answered:Array.isArray(raw.answered)?raw.answered.filter(id=>questions.some(q=>q.id===id)):[],question:questions.some(q=>q.id===raw.question)?raw.question:'home',topPick:ids.has(raw.topPick)?raw.topPick:null};}}catch{storageOK=false;}
try{const raw=JSON.parse(localStorage.getItem(preferenceKey));if(raw)prefs={size:Math.max(85,Math.min(150,Number(raw.size)||100)),motion:raw.motion===true,theme:raw.theme==='dark'?'dark':'light'};}catch{}
let route='',dogView='recommended',query='',shown=12,editSingle=false,preview=null,metric='score',pendingPick=null,toastTimer,drag=null,swipe=null;
const listQuestions=()=>activeQuestions(state.profile,state.answered);
const breed=id=>breeds.find(b=>b.id===id);
const dog=id=>dogProfiles[id];
const photo=id=>`../photos/${id}.jpg?v=57`;
const has=id=>state.answered.includes(id);
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}updateNavigation();}
function notify(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function setPrefs(){document.documentElement.dataset.theme=prefs.theme;document.documentElement.dataset.largeText=String(prefs.size>=125);document.documentElement.dataset.reducedMotion=String(prefs.motion);document.documentElement.style.setProperty('--text-scale',prefs.size/100);$('font-size').textContent=`${prefs.size}%`;$('smaller').disabled=prefs.size<=85;$('larger').disabled=prefs.size>=150;$('motion').checked=prefs.motion;$('theme-toggle').innerHTML=paw+` ${prefs.theme==='dark'?'Light mode':'Dark mode'}`;$('theme-toggle').setAttribute('aria-pressed',String(prefs.theme==='dark'));$('settings-theme').textContent=prefs.theme==='dark'?'Switch to light mode':'Switch to dark mode';try{localStorage.setItem(preferenceKey,JSON.stringify(prefs));}catch{}}
function ring(score,large=false){const v=Math.max(0,Math.min(100,Math.round(score)));return `<div class="ring${large?' large':''}" role="img" aria-label="${v}% profile fit"><svg viewBox="0 0 100 100" aria-hidden="true"><circle class="track" cx="50" cy="50" r="44"/><circle class="value" cx="50" cy="50" r="44" pathLength="100" stroke-dasharray="${v} ${100-v}"/></svg><span>${v}%</span></div>`;}
function meta(id){const d=dog(id);return `${d.sex||'Sex not provided'} · ${d.age?`Age ${d.age}`:'Age not provided'}`;}
function sourceNote(){return '<p class="screen-footer">Profile fit is a simplified dog-type estimate. Most identities are examples; Winnie, Link, Mit, and Monty include owner-confirmed details. These are not adoption listings.</p>';}
function pageTop(title,copy,actions=''){return `<header class="page-top"><div><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</header>`;}
function updateNavigation(){const active=listQuestions();$('nav-progress').textContent=`${active.filter(q=>has(q.id)).length}/${active.length}`;$('nav-compare').textContent=state.compare.length?`${state.compare.length} dogs`:'';document.querySelector('[data-route=quiz]').href=state.completed?'#review':'#quiz';document.querySelectorAll('[data-route]').forEach(a=>{const selected=a.dataset.route===route||(route==='review'&&a.dataset.route==='quiz');if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function go(hash){if(location.hash===`#${hash}`)showRoute();else location.hash=hash;}
function showRoute(){let next=location.hash.slice(1)||'welcome';if(next==='matches')next='dogs';if(next==='comparison')next='compare';if(!['welcome','quiz','review','dogs','discover','compare'].includes(next))next='welcome';if(next!=='compare')preview=null;route=next;document.body.classList.toggle('welcome-mode',route==='welcome');$('sidebar').classList.remove('menu-open');$('main').inert=false;$('menu-toggle').setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});const title=screen.querySelector('h1');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}}
function render(){screen.dataset.view=route;if(route==='welcome')renderWelcome();if(route==='quiz')renderQuestion();if(route==='review')renderReview();if(route==='dogs')renderDogs();if(route==='discover')renderDiscovery();if(route==='compare')renderComparison();updateNavigation();}
function renderWelcome(){const faces=['aussiedoodle','goldendoodle','chihuahua','long-haired-dachshund','havanese','cavalier'];screen.innerHTML=`<div class="welcome"><div class="welcome-tools"><button data-settings>Text size &amp; accessibility</button></div><section class="welcome-copy"><a href="#welcome" class="wordmark">Pawfect Match<span>.</span></a><h1>Your life.<br>Your kind of dog.</h1><p class="welcome-lead">Meet a dog who fits the way you live.</p><div class="welcome-actions"><a class="primary with-icon" href="${state.completed?'#review':'#quiz'}">${state.completed?'Revisit my answers':state.answered.length?'Continue matching':'Start matching'} ${paw}</a><button class="text-button" data-browse>Browse dogs first</button></div><p class="welcome-note">A few thoughtful questions. A personal shortlist. A clearer way to choose.</p></section><div class="welcome-pictures" aria-label="Meet some of the dogs">${faces.map(id=>`<figure><img class="portrait-${id}" src="${photo(id)}" alt="${dog(id).name}, ${breed(id).name}"><figcaption>${dog(id).name}</figcaption></figure>`).join('')}</div></div>`;}
function chapterButtons(current){const active=listQuestions();return chapters.map((chapter,i)=>{const qs=active.filter(q=>q.chapter===i);return `<button type="button" data-chapter="${i}" class="${current===i?'active':''}" ${current===i?'aria-current="step"':''}>${chapter.name}<small>${qs.filter(q=>has(q.id)).length}/${qs.length}</small></button>`;}).join('');}
function renderQuestion(){const active=listQuestions();let q=active.find(q=>q.id===state.question)||active[0];state.question=q.id;const index=active.indexOf(q),chapter=chapters[q.chapter],count=active.filter(q=>has(q.id)).length;
 let control='';if(q.type==='range'){control=`<div class="range-answer" data-unanswered="${!has(q.id)}"><label class="muted" for="answer">${q.short}</label><output id="answer-value" for="answer">${has(q.id)?answerText(q,state.profile[q.id]):'Move the slider to choose'}</output><input id="answer" name="${q.id}" type="range" min="${q.min}" max="${q.max}" step="${q.step}" value="${has(q.id)?state.profile[q.id]:q.min}" aria-label="${q.title}" aria-valuetext="${has(q.id)?answerText(q,state.profile[q.id]):'Not selected'}"><div class="range-ends"><span>${q.ends[0]}</span><span>${q.ends[1]}</span></div></div>`;}
 else if(q.type==='select'){control=`<label class="muted" for="answer">${q.short}</label><select id="answer" name="${q.id}" aria-label="${q.title}"><option value="" disabled ${!has(q.id)?'selected':''}>Choose an answer…</option>${q.options.map(([v,label])=>`<option value="${v}" ${has(q.id)&&String(state.profile[q.id])===v?'selected':''}>${label}</option>`).join('')}</select>`;}
 else control=`<div class="option-list" role="radiogroup" aria-labelledby="question-title">${q.options.map(([value,label])=>`<label class="option"><input type="radio" name="${q.id}" value="${value}" ${has(q.id)&&String(state.profile[q.id])===value?'checked':''}><span>${label}</span></label>`).join('')}</div>`;
 screen.innerHTML=`${pageTop(editSingle?'Fine-tune your answers.':'Let’s find your kind of dog.','Your answers save as you go.',`<a class="text-button" href="#review">Review answers</a>`)}<div class="question-layout"><aside class="chapter-panel"><nav class="chapter-nav" aria-label="Questionnaire chapters">${chapterButtons(q.chapter)}</nav><p>${chapter.note}</p><figure class="chapter-portrait"><img src="${photo(chapter.photo)}" alt="${chapter.dog}"><figcaption>Every dog has a different rhythm.</figcaption></figure></aside><form class="question-stage" id="question-form" novalidate><div class="progress-meta"><span>${chapter.name}</span><span id="answer-count">${count} of ${active.length} answered</span></div><div class="progress"><span id="answer-progress" style="width:${count/active.length*100}%"></span></div><h2 id="question-title">${q.title}</h2><p class="question-help">${q.help}</p>${control}<p class="question-error" id="question-error" role="alert" hidden>Choose an answer to continue.</p><p class="why">${q.why}</p><div class="question-bottom"><div>${index>0&&!editSingle?'<button type="button" class="text-button" data-question-back>Back</button>':''}<span class="save-state" id="question-save">${storageOK?'Saved on this device':'Storage unavailable · this visit only'}</span></div><button type="submit" class="primary">${editSingle?'Back to review':index===active.length-1?'Review my answers':'Continue'} →</button></div></form></div>`;
}
function setAnswer(target){const q=questions.find(q=>q.id===target.name);if(!q||target.value==='')return;state.profile=normalizeProfile({...state.profile,[q.id]:target.value});if(!has(q.id))state.answered.push(q.id);if(state.completed&&listQuestions().some(item=>!has(item.id)))state.completed=false;save();const active=listQuestions(),count=active.filter(q=>has(q.id)).length;if($('answer-value')){$('answer-value').textContent=answerText(q,state.profile[q.id]);target.setAttribute('aria-valuetext',$('answer-value').textContent);target.closest('.range-answer').dataset.unanswered='false';}$('question-error').hidden=true;$('answer-count').textContent=`${count} of ${active.length} answered`;$('answer-progress').style.width=`${count/active.length*100}%`;$('question-save').textContent=storageOK?'Saved on this device':'Saved for this visit only';document.querySelector('.chapter-nav').innerHTML=chapterButtons(q.chapter);}
function nextQuestion(){const active=listQuestions(),q=active.find(q=>q.id===state.question);if(!has(q.id)){$('question-error').hidden=false;screen.querySelector('input,select')?.focus();return;}const index=active.indexOf(q);if(editSingle||index===active.length-1){editSingle=false;go('review');return;}state.question=active[index+1].id;save();renderQuestion();window.scrollTo({top:0,behavior:'instant'});$('question-title').tabIndex=-1;$('question-title').focus({preventScroll:true});}
function renderReview(){const active=listQuestions(),missing=active.filter(q=>!has(q.id));screen.innerHTML=`${pageTop('Your life, at a glance.','Change any answer before meeting your dogs.')}<div class="review-grid">${chapters.map((chapter,i)=>`<section class="review-section"><h2>${chapter.name}</h2>${active.filter(q=>q.chapter===i).map(q=>`<div class="answer-row"><div><span>${q.short}</span><strong>${has(q.id)?answerText(q,state.profile[q.id]):'Not answered yet'}</strong></div><button data-edit-answer="${q.id}" aria-label="Edit ${q.short}">${has(q.id)?'Edit':'Answer'}</button></div>`).join('')}</section>`).join('')}</div>${has('alone')&&needsCarePlan(state.profile)?'<p class="care-note"><strong>A care plan needs attention.</strong> Your answers include longer days away without support. This caps model scores at 55% until you add a plan.</p>':''}<div class="review-footer"><p>${missing.length?`${missing.length} ${missing.length===1?'answer':'answers'} left before we can recommend dogs.`:'Ready to meet your dogs? You can revisit these answers anytime.'}</p><button class="primary" data-finish>${missing.length?'Finish my answers':'See my dogs'} →</button></div>`;}
function selectionStrip(){return state.compare.length?`<div class="selection-strip"><p>Selected for comparison: ${state.compare.map(id=>dog(id).name).join(', ')}.</p><a href="#compare">Compare ${state.compare.length} ${state.compare.length===1?'dog':'dogs'} →</a></div>`:'';}
function card({breed:b,score,fit}){const d=dog(b.id),saved=state.favorites.includes(b.id);const summary=state.completed?(fit.activity===100?'Activity fits your planned time.':'Needs more activity time than planned.')+' '+(fit.grooming===100?'Coat care fits your commitment.':'Allow more time for coat care.'):b.description;return `<article class="dog-card"><button class="card-photo" data-dog="${b.id}" aria-label="Meet ${d.name}"><img src="${photo(b.id)}" alt="${d.name}, ${b.name}" loading="lazy"><span class="photo-caption">${d.ownerProvided?'Owner details':'Example profile'}</span></button><div class="card-body"><div class="dog-heading"><h2>${d.name}</h2><button class="heart" data-save="${b.id}" aria-label="${saved?'Remove':'Save'} ${d.name}" aria-pressed="${saved}">${heart(saved)}</button></div><p class="dog-meta">${b.name}<br>${meta(b.id)}</p>${state.completed?`<div class="score-row">${ring(score)}<span class="score-label">Profile fit<br>Based on your answers</span></div>`:''}<p class="card-summary">${summary}</p><div class="card-actions"><button data-dog="${b.id}">Meet ${d.name}</button><label class="check"><input type="checkbox" data-compare="${b.id}" ${state.compare.includes(b.id)?'checked':''}> Compare</label></div></div></article>`;}
function libraryRows(){let ranked=rankBreeds(state.profile);if(dogView==='recommended')ranked=ranked.filter(r=>matchesCoat(r.breed,state.profile)).slice(0,6);if(dogView==='favorites')ranked=ranked.filter(r=>state.favorites.includes(r.breed.id));if(dogView==='browse')ranked.sort((a,b)=>a.breed.name.localeCompare(b.breed.name));const search=query.toLowerCase().replace(/[^a-z0-9]/g,'');return ranked.filter(r=>`${r.breed.name} ${dog(r.breed.id).name}`.toLowerCase().replace(/[^a-z0-9]/g,'').includes(search));}
function renderDogResults(){const results=$('dog-results');if(!results)return;if(dogView==='recommended'&&!state.completed){results.innerHTML='<div class="empty-state"><h2>A good match starts with you.</h2><p>Complete the questionnaire to see personalized recommendations. Browse is open whenever you want to explore.</p><a class="primary with-icon" href="#quiz">Start matching →</a></div>';$('library-count').textContent='Personalized recommendations appear after your questionnaire.';return;}
 const rows=libraryRows(),visible=rows.slice(0,shown);$('library-count').textContent=`${rows.length} ${rows.length===1?'dog':'dogs'}${query?' matching your search':dogView==='recommended'?' to start with':dogView==='favorites'?' saved':' in the catalog'}.`;
 results.innerHTML=visible.length?`<div class="dog-grid">${visible.map(card).join('')}</div>${visible.length<rows.length?`<button class="load-more" data-load-more>Show more dogs (${visible.length} of ${rows.length})</button>`:''}`:`<div class="empty-state"><h2>${query?'No dogs found.':'Your favorites will feel at home here.'}</h2><p>${query?'Try a dog’s name or a dog type.': 'Save a dog with the heart to keep them in your shortlist.'}</p><button data-browse>Browse all dogs</button></div>`;
}
function renderDogs(){screen.innerHTML=`${pageTop('Meet your possibilities.',state.completed?'A shortlist that starts with your life.':'Explore the dogs. Add your answers when you’re ready.',`<a class="text-button" href="#review">${state.answered.length?'Edit my answers':'Your questionnaire'}</a>`)}${state.topPick?`<div class="top-pick-strip"><img src="${photo(state.topPick)}" alt="${dog(state.topPick).name}"><p>Your top pick<br><strong>${dog(state.topPick).name}</strong></p><button data-dog="${state.topPick}">View profile</button></div>`:''}<div class="library-tools"><div class="tabs" aria-label="Dog library views">${[['recommended','Recommended'],['favorites','Favorites'],['browse','Browse']].map(([id,label])=>`<button data-dog-view="${id}" aria-pressed="${dogView===id}">${label}${id==='favorites'?` (${state.favorites.length})`:''}</button>`).join('')}</div><div class="search"><label for="dog-search">Find a dog</label><input type="search" id="dog-search" placeholder="Name or dog type" value="" autocomplete="off"></div></div><div id="selection-strip">${selectionStrip()}</div><p class="library-note" id="library-count" role="status"></p><div id="dog-results"></div>${sourceNote()}`;$('dog-search').value=query;renderDogResults();}
function fitSummary(row){const good=[['activity', 'Your activity time fits'],['training','Training fits your commitment'],['grooming','Coat care fits your commitment'],['size','Matches your size preference']].filter(([key])=>row.fit[key]===100).slice(0,2);return good.map(([,text])=>text).join('. ')+(good.length?'.':'Explore the care details before deciding.');}
function renderDiscovery(){if(!state.completed){screen.innerHTML=`${pageTop('Meet one dog at a time.','A short, personal round after your questionnaire.')}<div class="empty-state"><h2>Let’s get to know your routine.</h2><p>Finish your answers to start a round of ten dogs matched to your preferences.</p><a href="#quiz" class="primary with-icon">Continue matching →</a></div>`;return;}
 const eligible=breeds.filter(b=>matchesCoat(b,state.profile)),roundSize=Math.min(10,eligible.length),relevant=state.history.filter(h=>eligible.some(b=>b.id===h.id)).slice(0,roundSize),current=discoveryRound(state.profile,state.history)[0],likes=relevant.filter(h=>h.choice==='like').length;
 screen.innerHTML=`${pageTop('A little connection goes a long way.','Meet up to ten dogs. Like the ones you want to remember.',`<a class="text-button" href="#dogs">View my favorites →</a>`)}<div class="discover-layout"><div>${current?`<article class="discovery-card"><img data-swipe-image src="${photo(current.breed.id)}" alt="${dog(current.breed.id).name}, ${current.breed.name}" draggable="false"><div class="discovery-copy"><h2>${dog(current.breed.id).name}</h2><p class="dog-meta">${current.breed.name}<br>${meta(current.breed.id)}</p><div class="score-row">${ring(current.score)}<span class="score-label">Profile fit</span></div><p>${dog(current.breed.id).likes?`Loves ${dog(current.breed.id).likes.toLowerCase()}.`:current.breed.description}</p><button class="text-button" data-dog="${current.breed.id}">Meet ${dog(current.breed.id).name} in detail</button></div></article><div class="discover-buttons"><button data-decide="pass">Pass</button><button class="primary with-icon" data-decide="like">${heart(false)} Like ${dog(current.breed.id).name}</button></div>`:`<div class="empty-state"><h2>You’ve met your round.</h2><p>${likes?`${likes} ${likes===1?'dog is':'dogs are'} saved from this round.`:'No favorites this round. You can browse everyone, or try a new round.'}</p><a class="primary with-icon" href="#dogs">Visit your dogs →</a></div>`}</div><aside class="discover-side"><p class="round-meta">${current?`${relevant.length+1} of ${roundSize} dogs`:'Round complete'} · ${likes} liked</p><div class="progress"><span style="width:${relevant.length/roundSize*100}%"></span></div><h2>${current?'Why this dog?':'Keep exploring.'}</h2><p>${current?fitSummary(current):'Your saved favorites stay with you, even when you start again.'}</p>${current?`<h3>Care to consider</h3><p>${current.breed.watch}</p>`:''}<label for="discover-coat">Coat preference</label><select id="discover-coat">${[['any','All coat types'],['fluffy','Fluffy coats'],['sleek','Shorter coats']].map(([v,t])=>`<option value="${v}" ${state.profile.fluff===v?'selected':''}>${t}</option>`).join('')}</select><div class="side-actions"><button data-undo ${state.history.length?'':'disabled'}>Undo last choice</button><button data-restart ${state.history.length?'':'disabled'}>New round</button></div><p class="detail-note">Swipe the photo, use the buttons, or press the left/right arrow keys. Your choices help shape the next pick.</p></aside></div>${sourceNote()}`;
}
function decide(choice){const current=discoveryRound(state.profile,state.history)[0];if(!current)return;const id=current.breed.id,wasSaved=state.favorites.includes(id);state.history.push({id,choice,wasSaved});state.favorites=choice==='like'?[...new Set([...state.favorites,id])]:state.favorites.filter(x=>x!==id);save();renderDiscovery();notify(choice==='like'?`${dog(id).name} saved to Favorites.`:`Passed ${dog(id).name}.`);}
function toggleFavorite(id){const exists=state.favorites.includes(id);state.favorites=exists?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(route==='dogs')renderDogs();if($('dog-dialog').open)openDog(id,false);const scope=$('dog-dialog').open?$('dog-dialog'):screen;(scope.querySelector(`[data-save="${id}"]`)||$('dog-search'))?.focus({preventScroll:true});notify(exists?`${dog(id).name} removed from Favorites.`:`${dog(id).name} saved to Favorites.`);}
function toggleComparison(id,checked){if(checked&&state.compare.length>=3){notify('Choose up to three dogs. Remove one before adding another.');return false;}state.compare=checked?[...new Set([...state.compare,id])]:state.compare.filter(x=>x!==id);save();if(route==='dogs'){$('selection-strip').innerHTML=selectionStrip();}if($('dog-dialog').open)openDog(id,false);if(route==='compare')renderComparison();return true;}
function renderComparison(previewOnly=false){const rows=rankBreeds(preview===null?state.profile:{...state.profile,exercise:preview}),baseline=rankBreeds(state.profile);const ordered=state.compare.map(id=>rows.find(r=>r.breed.id===id));const sorted=[...ordered].sort((a,b)=>b.score-a.score);let lead='Select two or three dogs to see how their fits compare.';
 if(ordered.length&&state.completed){
  const winner=sorted[0],others=sorted.slice(1),name=dog(winner.breed.id).name;
  const differences=[['activity','activity time'],['training','training commitment'],['grooming','coat care'],['size','size preference'],['space','home space']].filter(([key])=>others.some(other=>winner.fit[key]>other.fit[key])).slice(0,2).map(([,text])=>text);
  lead=!others.length?`${name} is selected. Add another dog to compare.`:others.every(other=>other.score===winner.score)?`These dogs tie at ${winner.score}%. Compare their care needs before choosing.`:`${name} leads at ${winner.score}%${differences.length?`, with a stronger fit for your ${differences.join(' and ')}`:''}.`;
 }

 const markup=`${pageTop('Compare your dogs.','A clearer choice, side by side.',`<a class="text-button" href="#dogs">Choose dogs →</a>`)}${!state.completed?'<p class="care-note">Complete your questionnaire to reveal match scores. You can still compare dog-type needs below. <a href="#quiz">Start matching →</a></p>':''}<div class="compare-intro"><p id="compare-insight">${preview!==null?'<strong>Preview.</strong> ':''}${lead}</p></div>${ordered.length?`<div class="compare-tools"><p>Drag a Move handle to arrange your dogs.<br>Earlier/later buttons also work with a keyboard or touch.</p><label for="compare-metric">Compare by<select id="compare-metric">${[['score','Overall profile fit'],['exercise','Activity target'],['grooming','Grooming commitment'],['training','Training & enrichment']].map(([v,t])=>`<option value="${v}" ${metric===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="compare-grid" style="--columns:${ordered.length}">${ordered.map(row=>compareCard(row,baseline)).join('')}</div>${state.completed?`<details class="explorer"><summary>What if my routine changed?</summary><div class="explorer-content"><label for="experiment">Preview daily walks &amp; play</label><output for="experiment" id="experiment-value">${duration(preview===null?state.profile.exercise:preview)}</output><input type="range" id="experiment" min="0" max="240" step="1" value="${preview===null?state.profile.exercise:preview}" aria-valuetext="${duration(preview===null?state.profile.exercise:preview)}"><div class="range-ends"><span>0 minutes</span><span>4 hours</span></div><p id="experiment-note">${preview===null?'Explore a different activity time. Your saved answers stay unchanged.':'Preview only. The comparison above reflects this time. Save it only if it fits your real routine.'}</p><div class="page-actions"><button data-apply-preview class="primary" ${preview===null?'disabled':''}>Use this activity time</button><button data-reset-preview ${preview===null?'disabled':''}>Reset preview</button></div></div></details>${fitTable(ordered)}`:''}`:`<div class="empty-state"><h2>Make a little room for comparison.</h2><p>Select Compare on a dog’s card. You can bring up to three dogs here.</p><a href="#dogs" class="primary with-icon">Find your dogs →</a></div>`}${sourceNote()}`;
 if(!previewOnly){screen.innerHTML=markup;return;}
 const template=document.createElement('template');template.innerHTML=markup;
 for(const selector of ['.compare-intro','.compare-grid','.fit-table']){const current=screen.querySelector(selector),next=template.content.querySelector(selector);if(current&&next)current.replaceWith(next);}
 $('experiment-value').textContent=duration(preview);$('experiment').setAttribute('aria-valuetext',duration(preview));
 $('experiment-note').textContent='Preview only. The comparison above reflects this time. Save it only if it fits your real routine.';
 screen.querySelector('[data-apply-preview]').disabled=false;screen.querySelector('[data-reset-preview]').disabled=false;
}
function compareCard(row,baseline){
 const b=row.breed,d=dog(b.id),index=state.compare.indexOf(b.id),delta=row.score-baseline.find(r=>r.breed.id===b.id).score;
 const score=metric==='score'?(state.completed?`<div class="score-row">${ring(row.score,true)}<span class="score-label">${preview===null?'Profile fit':'Preview fit'}</span></div>`:'<small>Answer the quiz for a score</small>'):'';
 return `<article class="compare-card" data-compared-id="${b.id}"><div class="move-tools"><button class="drag" data-drag="${b.id}" aria-label="Move ${d.name}. Drag to reorder.">Move ${d.name}</button><button data-move="${b.id}" data-direction="-1" aria-label="Move ${d.name} earlier" ${index===0?'disabled':''}>←</button><button data-move="${b.id}" data-direction="1" aria-label="Move ${d.name} later" ${index===state.compare.length-1?'disabled':''}>→</button></div><div class="compare-identity"><div><h2>${d.name}</h2><p class="dog-meta">${b.name}<br>${meta(b.id)}</p></div>${score}</div><img src="${photo(b.id)}" alt="${d.name}, ${b.name}">${metric!=='score'?`<p class="metric-value">${metric==='exercise'?duration(b.exercise):`${b[metric]} / 3`} <small>${metric==='exercise'?'activity target':'commitment level'}</small></p>`:''}${preview!==null?`<p class="delta">${delta>=0?'+':''}${delta} points vs. saved answers</p>`:''}<button class="pick ${state.topPick===b.id?'primary':''}" data-pick="${b.id}">${state.topPick===b.id?'Your top pick':'Mark as top pick'}</button><button class="remove text-button" data-remove-compare="${b.id}">Remove ${d.name}</button></article>`;
}
function fitTable(rows){const metrics=[['activity','Activity'],['training','Training'],['grooming','Grooming'],['size','Size'],['space','Home space'],['coat','Coat preference']];return `<table class="fit-table"><caption>Where each dog fits</caption><thead><tr><th scope="col">Your priorities</th>${rows.map(r=>`<th scope="col">${dog(r.breed.id).name}</th>`).join('')}</tr></thead><tbody>${metrics.map(([key,label])=>`<tr><th scope="row">${label}</th>${rows.map(r=>`<td>${Math.round(r.fit[key])}%<div class="mini-bar" aria-hidden="true"><i style="width:${r.fit[key]}%"></i></div></td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function moveDog(source,target){state.compare=reorderCompared(state.compare,source,target);save();renderComparison();(screen.querySelector(`[data-move="${source}"]:not(:disabled)`)||screen.querySelector(`[data-drag="${source}"]`))?.focus({preventScroll:true});notify(`${dog(source).name} moved to position ${state.compare.indexOf(source)+1}.`);}
function openDog(id,show=true){const b=breed(id),d=dog(id),row=rankBreeds(state.profile).find(r=>r.breed.id===id);const known=[d.sex,d.age?`Age ${d.age}`:null].filter(Boolean).join(' · ');const notes=state.completed?[['Activity',row.fit.activity===100?'Fits your planned time.':'Needs more activity than planned.'],['Training',row.fit.training===100?'Fits your commitment.':'Needs more enrichment time.'],['Grooming',row.fit.grooming===100?'Fits your commitment.':'Needs more coat care.'],['Size',row.fit.size===100?'Matches your preference.':'Outside your preferred size.']]:[];$('dog-dialog-content').innerHTML=`<div class="dialog-header"><div><h2 id="dog-dialog-title">Meet ${d.name}.</h2><p class="muted">${b.name}${known?` · ${known}`:''}</p></div><button data-close="dog-dialog">Close</button></div><div class="detail-layout"><img src="${photo(id)}" alt="${d.name}, ${b.name}"><div class="detail-copy">${state.completed?`<div class="score-row">${ring(row.score,true)}<span class="score-label">Profile fit</span></div>`:''}<p>${b.description}</p>${d.likes?`<h3>Loves</h3><p>${d.likes}.</p>`:''}${notes.length?`<h3>Your fit</h3><ul>${notes.map(([label,note])=>`<li><strong>${label}:</strong> ${note}</li>`).join('')}</ul>`:''}<h3>Care</h3><p>${b.watch}</p><a href="${b.url}" target="_blank" rel="noopener">Read the dog-type guide ↗</a><p class="detail-note">${d.ownerProvided?'Name and supplied details come from the owner. Other estimates describe the dog type.':'This is an example identity and a dog-type profile, not a verified adoption listing.'}</p></div></div><div class="dialog-actions"><button data-save="${id}" class="with-icon">${heart(state.favorites.includes(id))} ${state.favorites.includes(id)?'Saved to favorites':'Save to favorites'}</button><label class="check"><input type="checkbox" data-compare="${id}" ${state.compare.includes(id)?'checked':''}> Compare ${d.name}</label><button data-pick="${id}" class="primary">${state.topPick===id?'Your top pick':'Mark as top pick'}</button></div>`;if(show)$('dog-dialog').showModal();}
function openPick(id){pendingPick=id;if($('dog-dialog').open)$('dog-dialog').close();$('confetti').innerHTML='';$('pick-title').textContent=`Mark ${dog(id).name} as your top pick?`;$('pick-copy').textContent='This saves your favorite choice. You can keep exploring or change your top pick later.';$('pick-photo').src=photo(id);$('pick-photo').alt=dog(id).name;$('confirm-pick').hidden=false;$('confirm-pick').textContent=`Yes, choose ${dog(id).name}`;$('pick-dialog').showModal();}
function confirmPick(){if(!pendingPick)return;state.topPick=pendingPick;if(!state.favorites.includes(pendingPick))state.favorites.push(pendingPick);save();$('pick-title').textContent=`${dog(pendingPick).name} is your top pick!`;$('pick-copy').textContent='A little more clarity. A new favorite to remember.';$('confirm-pick').hidden=true;if(!prefs.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)$('confetti').innerHTML=Array.from({length:55},(_,i)=>`<i style="--x:${i*37%100}%;--delay:${i%7*.1}s;--color:${['#385c9e','#8ca9cf','#b9d0e9'][i%3]};--turn:${i*53}deg"></i>`).join('');render();}
// Screen interactions use delegation so filters and live charts keep their controls.
document.addEventListener('click',event=>{if(event.target.closest('.skip')){event.preventDefault();$('main').focus();return;}const button=event.target.closest('button');if(!button)return;if(button.dataset.close){$(button.dataset.close).close();return;}if(button.hasAttribute('data-settings')){$('settings-dialog').showModal();return;}if(button.hasAttribute('data-browse')){dogView='browse';query='';shown=12;go('dogs');return;}if(button.dataset.chapter!==undefined){editSingle=false;state.question=questions.find(q=>q.chapter===Number(button.dataset.chapter)).id;save();renderQuestion();return;}if(button.hasAttribute('data-question-back')){const qs=listQuestions(),i=qs.findIndex(q=>q.id===state.question);state.question=qs[Math.max(0,i-1)].id;save();renderQuestion();return;}if(button.dataset.editAnswer){state.question=button.dataset.editAnswer;editSingle=true;save();go('quiz');return;}if(button.hasAttribute('data-finish')){const missing=listQuestions().find(q=>!has(q.id));if(missing){state.question=missing.id;editSingle=false;save();go('quiz');return;}state.completed=true;save();dogView='recommended';query='';go('dogs');notify('Your personal shortlist is ready.');return;}if(button.dataset.dogView){dogView=button.dataset.dogView;shown=12;renderDogs();return;}if(button.hasAttribute('data-load-more')){shown+=12;renderDogResults();return;}if(button.dataset.save){toggleFavorite(button.dataset.save);return;}if(button.dataset.dog){openDog(button.dataset.dog);return;}if(button.dataset.pick){openPick(button.dataset.pick);return;}if(button.dataset.decide){decide(button.dataset.decide);return;}if(button.hasAttribute('data-undo')){const last=state.history.pop();if(!last)return;state.favorites=last.wasSaved?[...new Set([...state.favorites,last.id])]:state.favorites.filter(id=>id!==last.id);save();renderDiscovery();notify('Last choice undone.');return;}if(button.hasAttribute('data-restart')){state.history=[];save();renderDiscovery();notify('New round. Your favorites are kept.');return;}if(button.dataset.removeCompare){toggleComparison(button.dataset.removeCompare,false);return;}if(button.dataset.move){const source=button.dataset.move,target=state.compare[state.compare.indexOf(source)+Number(button.dataset.direction)];if(target)moveDog(source,target);return;}if(button.hasAttribute('data-reset-preview')){preview=null;renderComparison();notify('Preview cleared. Saved answers kept.');return;}if(button.hasAttribute('data-apply-preview')){if(preview===null)return;state.profile.exercise=preview;if(!has('exercise'))state.answered.push('exercise');preview=null;save();renderComparison();notify('Activity time saved. Recommendations updated.');return;}});
document.addEventListener('submit',event=>{if(event.target.id==='question-form'){event.preventDefault();nextQuestion();}});
document.addEventListener('input',event=>{const el=event.target;if(el.closest('#question-form'))setAnswer(el);if(el.id==='dog-search'){query=el.value;shown=12;renderDogResults();}if(el.id==='experiment'){preview=Number(el.value);renderComparison(true);}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.compare){if(!toggleComparison(el.dataset.compare,el.checked))el.checked=false;}if(el.id==='discover-coat'){state.profile.fluff=el.value;save();renderDiscovery();}if(el.id==='compare-metric'){metric=el.value;renderComparison();}});
document.addEventListener('pointerup',event=>{if(event.target.matches('#question-form input[type=range]'))setAnswer(event.target);});
document.addEventListener('keydown',event=>{if(event.target.matches('#question-form input[type=range]')&&[' ','Enter'].includes(event.key)){event.preventDefault();setAnswer(event.target);}if(route==='discover'&&!document.querySelector('dialog[open]')&&!event.target.matches('input,select,textarea,button')){if(event.key==='ArrowLeft'){event.preventDefault();decide('pass');}if(event.key==='ArrowRight'){event.preventDefault();decide('like');}}if(event.key==='Escape'){cancelDrag();if($('sidebar').classList.contains('menu-open')){$('sidebar').classList.remove('menu-open');$('main').inert=false;$('menu-toggle').setAttribute('aria-expanded','false');$('menu-toggle').focus();}}});
screen.addEventListener('pointerdown',event=>{if(event.target.matches('[data-swipe-image]')&&event.button===0){swipe={x:event.clientX,y:event.clientY,pointer:event.pointerId};event.target.setPointerCapture(event.pointerId);return;}const handle=event.target.closest('[data-drag]');if(!handle||event.button!==0)return;drag={id:handle.dataset.drag,x:event.clientX,y:event.clientY,pointer:event.pointerId};handle.setPointerCapture(event.pointerId);});
screen.addEventListener('pointermove',event=>{if(swipe&&event.pointerId===swipe.pointer){const dx=event.clientX-swipe.x,dy=event.clientY-swipe.y;if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>20){swipe=null;screen.querySelector('.discovery-card').style.transform='';return;}if(!prefs.motion)screen.querySelector('.discovery-card').style.transform=`translateX(${Math.max(-70,Math.min(70,dx))}px)`;return;}if(!drag||event.pointerId!==drag.pointer)return;document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-compared-id]');if(target&&target.dataset.comparedId!==drag.id)target.classList.add('drop-target');});
function cancelDrag(){drag=null;document.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));}
screen.addEventListener('pointerup',event=>{if(swipe){const dx=event.clientX-swipe.x,dy=event.clientY-swipe.y;swipe=null;screen.querySelector('.discovery-card').style.transform='';if(Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.2)decide(dx>0?'like':'pass');return;}if(!drag)return;const source=drag.id,distance=Math.hypot(event.clientX-drag.x,event.clientY-drag.y),target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-compared-id]')?.dataset.comparedId;cancelDrag();if(distance>16&&target&&source!==target)moveDog(source,target);});
screen.addEventListener('pointercancel',()=>{cancelDrag();swipe=null;const card=screen.querySelector('.discovery-card');if(card)card.style.transform='';});
$('menu-toggle').addEventListener('click',()=>{const open=$('sidebar').classList.toggle('menu-open');$('menu-toggle').setAttribute('aria-expanded',String(open));$('main').inert=open;});
function toggleTheme(){prefs.theme=prefs.theme==='dark'?'light':'dark';setPrefs();}
$('theme-toggle').addEventListener('click',toggleTheme);$('settings-theme').addEventListener('click',toggleTheme);
$('settings-open').addEventListener('click',()=>$('settings-dialog').showModal());
$('smaller').addEventListener('click',()=>{prefs.size=Math.max(85,prefs.size-10);setPrefs();});
$('larger').addEventListener('click',()=>{prefs.size=Math.min(150,prefs.size+10);setPrefs();});
$('reset-size').addEventListener('click',()=>{prefs.size=100;setPrefs();});
$('motion').addEventListener('change',event=>{prefs.motion=event.target.checked;setPrefs();});
$('reset-open').addEventListener('click',()=>{$('settings-dialog').close();$('reset-dialog').showModal();});
$('reset-confirm').addEventListener('click',()=>{state=fresh();preview=null;editSingle=false;query='';dogView='recommended';save();$('reset-dialog').close();go('quiz');notify('Prototype reset. Ready for a fresh start.');});
$('confirm-pick').addEventListener('click',confirmPick);
$('credits-open').addEventListener('click',()=>$('credits-dialog').showModal());
window.addEventListener('hashchange',showRoute);
new ResizeObserver(entries=>{document.documentElement.style.setProperty('--mobile-bar',`${entries[0].target.offsetHeight}px`);}).observe(document.querySelector('.mobile-header'));
setPrefs();showRoute();
